<script setup>
import { computed,inject,nextTick,onBeforeUnmount,onMounted,ref } from 'vue'
import { Alert,Button,Empty,Input,Modal } from 'ant-design-vue'
import { useDocumentRead } from './documentState.js'
import { documentApi } from './documentApi.js'
import { artifactMarkdown,imageObjectUrl,jsonPaths } from './documentModel.js'
import ReadState from './ReadState.vue'
import { remembered,useBrowseMemory } from './browseMemory.js'
const props=defineProps({documentId:String,taskId:String,memory:{type:Object,default:()=>({})}})
const state=useDocumentRead('artifacts'),content=useDocumentRead('content'),selected=ref(null),image=ref(''),expanded=ref(false),search=ref(''),notice=ref(''),downloading=ref(false)
const filter=remembered(props.memory,'filter',''),restoreScroll=useBrowseMemory(props.memory,{filter})
const items=computed(()=>(state.data.value?.artifacts||[]).filter(item=>`${item.fileName||''} ${item.artifactTypeName||''}`.toLocaleLowerCase().includes(filter.value.toLocaleLowerCase())))
const position=computed(()=>items.value.findIndex(item=>item.artifactId===selected.value?.artifactId))
function step(delta){const item=items.value[position.value+delta];if(item)open(item)}
const popupContainer=inject('admin-next-container');let trigger,controller,disposed=false,previewEpoch=0;const urls=new Set()
const payload=()=>({documentId:props.documentId,taskId:props.taskId || undefined})
function read(){return state.read(payload())}
function clearImage(){if(image.value){URL.revokeObjectURL(image.value);urls.delete(image.value);image.value=''}}
async function open(item,event){const wasOpen=Boolean(selected.value),owner=++previewEpoch;if(!selected.value&&event?.currentTarget)trigger=event.currentTarget;clearImage();selected.value=item;await nextTick();if(wasOpen)document.querySelector('.admin-next-doc-artifact-dialog')?.focus();expanded.value=false;search.value='';await content.read({...payload(),artifactId:item.artifactId});if(!disposed&&owner===previewEpoch&&selected.value?.artifactId===item.artifactId){image.value=imageObjectUrl(content.data.value);if(image.value)urls.add(image.value)}}
function restoreFocus(){requestAnimationFrame(()=>{if(!disposed&&trigger?.isConnected)trigger.focus({preventScroll:true})})}
function close(){previewEpoch++;selected.value=null;content.data.value=null;clearImage()}
const formatted=computed(()=>{const raw=String(content.data.value?.content||'');if(content.data.value?.json){try{return JSON.stringify(JSON.parse(raw),null,2)}catch{return raw}}return raw})
const paths=computed(()=>content.data.value?.json?jsonPaths(content.data.value.content,search.value):[])
const visible=computed(()=>formatted.value.slice(0,expanded.value?undefined:20000))
const matches=computed(()=>search.value?String(content.data.value?.content||'').split(search.value).length-1:0)
async function copy(){try{await navigator.clipboard.writeText(content.data.value?.content || '');notice.value='已复制内容'}catch{notice.value='复制失败，请手动选择内容'}}
async function download(item){if(downloading.value)return;downloading.value=true;notice.value='';controller=new AbortController();try{const result=await documentApi.download({...payload(),artifactId:item.artifactId},controller.signal);if(disposed)return;const url=URL.createObjectURL(result.blob);urls.add(url);const a=document.createElement('a');a.href=url;a.download=result.fileName;a.click();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url)},1000)}catch(e){if(!disposed&&e.name!=='AbortError')notice.value=e.message}finally{if(!disposed)downloading.value=false}}
onMounted(async()=>{await read();restoreScroll()});onBeforeUnmount(()=>{disposed=true;controller?.abort();for(const url of urls)URL.revokeObjectURL(url);urls.clear()})
</script>
<template><section class="admin-next-doc-panel"><div class="admin-next-doc-row"><h2>解析产物</h2><Button :disabled="state.loading.value" @click="read">刷新产物</Button></div><ReadState :state="state" label="解析产物" @retry="read" /><p v-if="notice" role="status">{{ notice }}</p><Empty v-if="state.data.value&&!state.data.value.artifacts?.length" description="暂无解析产物" /><div class="admin-next-doc-toolbar"><label for="artifact-list-search" class="chat-next-sr-only">搜索产物文件名</label><Input id="artifact-list-search" v-model:value="filter" placeholder="搜索产物文件名" /></div><Empty v-if="state.data.value?.artifacts?.length&&!items.length" description="没有匹配产物" /><ul class="admin-next-doc-items"><li v-for="item in items" :key="item.artifactId"><div><strong>{{ item.fileName || item.artifactTypeName }}</strong><span class="admin-next-doc-muted">{{ item.artifactTypeName }} · {{ item.parserName }} {{ item.parserVersion }} · {{ item.size ?? '—' }} B</span></div><div class="admin-next-doc-toolbar"><Button :disabled="item.viewable===false" @click="open(item,$event)">预览</Button><Button :disabled="downloading" @click="download(item)">下载</Button></div></li></ul>
<Modal wrap-class-name="admin-next-doc-artifact-dialog" :open="Boolean(selected)" :title="selected?.fileName || '产物预览'"  :width="900" :get-container="popupContainer" centered destroy-on-close @cancel="close" @after-close="restoreFocus"><ReadState :state="content" label="预览" @retry="open(selected,{currentTarget:trigger})" /><template v-if="content.data.value"><div class="admin-next-doc-toolbar"><label for="artifact-search" class="chat-next-sr-only">搜索产物内容</label><Input id="artifact-search" v-model:value="search" placeholder="搜索内容" /><span v-if="search">{{ matches }} 处匹配</span><Button @click="copy">复制内容</Button></div><p class="admin-next-doc-muted">接口返回 {{ content.data.value.contentLength ?? String(content.data.value.content || '').length }} 字符</p><img v-if="image" :src="image" :alt="selected.fileName" class="admin-next-doc-preview-image" /><p v-else-if="content.data.value.image" role="status">图片格式不可安全预览，请下载查看。</p><div v-else-if="content.data.value.markdown" class="admin-next-doc-markdown" v-html="artifactMarkdown(visible)"></div><pre v-else>{{ visible }}</pre><section v-if="content.data.value.json&amp;&amp;search"><h3>JSON 路径匹配（最多 50 项）</h3><ul><li v-for="(item,index) in paths" :key="index"><code>{{ item.path }}</code>：{{ item.value }}</li></ul><p v-if="!paths.length">未找到匹配路径。</p></section><Button v-if="formatted.length>20000" @click="expanded=!expanded">{{ expanded?'收起内容':'展开全部已加载内容' }}</Button></template><template #footer><div class="admin-next-doc-modal-footer"><Button @click="close">返回产物列表</Button><span class="admin-next-doc-muted">本列表 {{ position+1 }} / {{ items.length }}</span><div class="admin-next-doc-toolbar"><Button :disabled="position<=0||content.loading.value" @click="step(-1)">上一个产物</Button><Button :disabled="position<0||position>=items.length-1||content.loading.value" @click="step(1)">下一个产物</Button></div></div></template></Modal></section></template>
